const items = $input.all();
const rows = items.map(i => i.json).filter(r => r && r.date);

const now = new Date();
const msDay = 24 * 60 * 60 * 1000;
const thisStart = new Date(now.getTime() - 7 * msDay);
const prevStart = new Date(now.getTime() - 14 * msDay);

function num(v) {
  const n = parseFloat(String(v == null ? '' : v).replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? 0 : n;
}
function parseDate(d) {
  const t = new Date(d);
  return isNaN(t.getTime()) ? null : t;
}

const sp = {};
const pr = {};
function ensureSp(name) {
  if (!sp[name]) sp[name] = { revenueThis: 0, revenueLast: 0, unitsThis: 0, unitsLast: 0, wonDeals: 0, totalDeals: 0 };
  return sp[name];
}
function ensurePr(name) {
  if (!pr[name]) pr[name] = { revenueThis: 0, revenueLast: 0, unitsThis: 0, unitsLast: 0 };
  return pr[name];
}

for (const r of rows) {
  const d = parseDate(r.date);
  if (!d) continue;
  const isThis = d >= thisStart && d <= now;
  const isLast = d >= prevStart && d < thisStart;
  if (!isThis && !isLast) continue;
  const rev = num(r.revenue);
  const units = num(r.units);
  const person = String(r.salesperson || 'Unknown').trim();
  const product = String(r.product || 'Unknown').trim();
  const s = ensureSp(person);
  const p = ensurePr(product);
  if (isThis) {
    s.revenueThis += rev; s.unitsThis += units;
    p.revenueThis += rev; p.unitsThis += units;
    s.totalDeals += 1;
    if (String(r.deal_status || '').trim().toLowerCase() === 'won') s.wonDeals += 1;
  } else {
    s.revenueLast += rev; s.unitsLast += units;
    p.revenueLast += rev; p.unitsLast += units;
  }
}

function pct(cur, prev) {
  if (prev === 0) return null;
  return Math.round(((cur - prev) / prev) * 1000) / 10;
}
function r2(n) { return Math.round(n * 100) / 100; }

const salespeople = {};
for (const [name, v] of Object.entries(sp)) {
  salespeople[name] = {
    revenueThis: r2(v.revenueThis),
    revenueLast: r2(v.revenueLast),
    revenuePctChange: pct(v.revenueThis, v.revenueLast),
    unitsThis: v.unitsThis,
    unitsLast: v.unitsLast,
    unitsPctChange: pct(v.unitsThis, v.unitsLast),
    wonDeals: v.wonDeals,
    totalDeals: v.totalDeals,
    closeRate: v.totalDeals > 0 ? Math.round((v.wonDeals / v.totalDeals) * 1000) / 1000 : 0,
  };
}
const products = {};
for (const [name, v] of Object.entries(pr)) {
  products[name] = {
    revenueThis: r2(v.revenueThis),
    revenueLast: r2(v.revenueLast),
    revenuePctChange: pct(v.revenueThis, v.revenueLast),
    unitsThis: v.unitsThis,
    unitsLast: v.unitsLast,
    unitsPctChange: pct(v.unitsThis, v.unitsLast),
  };
}

const weekEnding = now.toISOString().slice(0, 10);
return [{ json: { weekEnding, rowsProcessed: rows.length, salespeople, products } }];

const data = $input.first().json;
const sp = data.salespeople || {};
const pr = data.products || {};
const flags = [];

for (const [name, v] of Object.entries(sp)) {
  if (v.revenuePctChange !== null && v.revenuePctChange < -20) {
    flags.push({ type: 'revenue_drop', name, revenueThis: v.revenueThis, revenueLast: v.revenueLast, revenuePctChange: v.revenuePctChange });
  }
  if (v.closeRate < 0.15) {
    flags.push({ type: 'low_close_rate', name, closeRate: v.closeRate, wonDeals: v.wonDeals, totalDeals: v.totalDeals });
  }
}
for (const [name, v] of Object.entries(pr)) {
  if (v.unitsPctChange !== null && v.unitsPctChange < -30) {
    flags.push({ type: 'product_units_drop', name, unitsThis: v.unitsThis, unitsLast: v.unitsLast, unitsPctChange: v.unitsPctChange });
  }
  if (v.unitsThis === 0 && v.unitsLast > 0) {
    flags.push({ type: 'product_zero_sales', name, unitsThis: 0, unitsLast: v.unitsLast });
  }
}

return [{
  json: {
    weekEnding: data.weekEnding,
    rowsProcessed: data.rowsProcessed,
    numbers: { salespeople: sp, products: pr },
    flags,
    flagCount: flags.length,
  },
}];

