const data = $('Flag Problems').first().json;

let text = '';
try {
  text = $('Write Report').first().json.output || '';
} catch (e) { text = ''; }

// Pull the JSON out even if the model wrapped it in fences
let ai = null;
try {
  let raw = String(text).replace(/```json/gi, '').replace(/```/g, '').trim();
  const s = raw.indexOf('{'), e = raw.lastIndexOf('}');
  if (s !== -1 && e !== -1) raw = raw.slice(s, e + 1);
  ai = JSON.parse(raw);
} catch (e) { ai = null; }

if (!ai || typeof ai !== 'object') {
  ai = {
    summary: 'The written summary could not be generated this week. The numbers below are still correct.',
    top_performers: '', underperformers: '', product_movement: '',
    flagged_problems: [], actions: [],
  };
}

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const money = (n) => '$' + Number(n || 0).toLocaleString('en-US');

const people = Object.entries(data.numbers.salespeople || {});
const products = Object.entries(data.numbers.products || {});

const totalThis = people.reduce((s, [, v]) => s + (v.revenueThis || 0), 0);
const totalLast = people.reduce((s, [, v]) => s + (v.revenueLast || 0), 0);
const totalPct = totalLast === 0 ? null : Math.round(((totalThis - totalLast) / totalLast) * 1000) / 10;

// Colour a percent change. Grey when there is no basis for comparison.
const delta = (p) => {
  if (p === null || p === undefined) return '<span style="color:#8a8a8a;">n/a</span>';
  const up = p >= 0;
  const colour = up ? '#1a7f4b' : '#b3261e';
  return '<span style="color:' + colour + ';font-weight:600;">' + (up ? '+' : '') + p + '%</span>';
};

const th = 'style="padding:10px 12px;text-align:left;font-size:12px;letter-spacing:.04em;text-transform:uppercase;color:#6b6b6b;border-bottom:1px solid #e3e3e3;font-weight:600;"';
const thR = 'style="padding:10px 12px;text-align:right;font-size:12px;letter-spacing:.04em;text-transform:uppercase;color:#6b6b6b;border-bottom:1px solid #e3e3e3;font-weight:600;"';
const td = 'style="padding:11px 12px;border-bottom:1px solid #f0f0f0;font-size:14px;color:#1c1c1c;"';
const tdR = 'style="padding:11px 12px;border-bottom:1px solid #f0f0f0;font-size:14px;color:#1c1c1c;text-align:right;"';

const section = (title, body) => body ? (
  '<tr><td style="padding:22px 28px 0 28px;">' +
  '<div style="font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:#6b6b6b;font-weight:600;margin-bottom:6px;">' + esc(title) + '</div>' +
  '<div style="font-size:15px;line-height:1.6;color:#1c1c1c;">' + esc(body) + '</div>' +
  '</td></tr>') : '';

// People table, biggest earner first
const peopleRows = people
  .sort((a, b) => (b[1].revenueThis || 0) - (a[1].revenueThis || 0))
  .map(([name, v]) => {
    const close = Math.round((v.closeRate || 0) * 100);
    const lowClose = close < 15 && v.totalDeals >= 3;
    return '<tr>' +
      '<td ' + td + '>' + esc(name) + '</td>' +
      '<td ' + tdR + '>' + money(v.revenueThis) + '</td>' +
      '<td ' + tdR + '>' + money(v.revenueLast) + '</td>' +
      '<td ' + tdR + '>' + delta(v.revenuePctChange) + '</td>' +
      '<td ' + tdR + '>' + (lowClose ? '<span style="color:#b3261e;font-weight:600;">' + close + '%</span>' : close + '%') + '</td>' +
      '</tr>';
  }).join('');

const productRows = products
  .sort((a, b) => (b[1].revenueThis || 0) - (a[1].revenueThis || 0))
  .map(([name, v]) => {
    const stalled = v.unitsThis === 0 && v.unitsLast > 0;
    return '<tr>' +
      '<td ' + td + '>' + esc(name) + (stalled ? ' <span style="color:#b3261e;font-size:12px;">stalled</span>' : '') + '</td>' +
      '<td ' + tdR + '>' + (v.unitsThis || 0) + '</td>' +
      '<td ' + tdR + '>' + (v.unitsLast || 0) + '</td>' +
      '<td ' + tdR + '>' + delta(v.unitsPctChange) + '</td>' +
      '<td ' + tdR + '>' + money(v.revenueThis) + '</td>' +
      '</tr>';
  }).join('');

const flagList = Array.isArray(ai.flagged_problems) ? ai.flagged_problems : [];
const flagBlock = flagList.length
  ? '<tr><td style="padding:22px 28px 0 28px;">' +
    '<div style="font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:#6b6b6b;font-weight:600;margin-bottom:8px;">Flagged problems</div>' +
    flagList.map(f =>
      '<div style="border-left:3px solid #b3261e;background:#fdf3f2;padding:10px 14px;margin-bottom:8px;font-size:14px;line-height:1.55;color:#1c1c1c;">' + esc(f) + '</div>'
    ).join('') + '</td></tr>'
  : '<tr><td style="padding:22px 28px 0 28px;">' +
    '<div style="border-left:3px solid #1a7f4b;background:#f1f8f3;padding:10px 14px;font-size:14px;color:#1c1c1c;">Nothing was flagged this week.</div>' +
    '</td></tr>';

const actions = Array.isArray(ai.actions) ? ai.actions : [];
const actionBlock = actions.length
  ? '<tr><td style="padding:22px 28px 0 28px;">' +
    '<div style="font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:#6b6b6b;font-weight:600;margin-bottom:8px;">Suggested actions</div>' +
    '<ol style="margin:0;padding-left:20px;font-size:15px;line-height:1.7;color:#1c1c1c;">' +
    actions.map(a => '<li style="margin-bottom:4px;">' + esc(a) + '</li>').join('') +
    '</ol></td></tr>'
  : '';

const table = (title, head, rows) =>
  '<tr><td style="padding:24px 28px 0 28px;">' +
  '<div style="font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:#6b6b6b;font-weight:600;margin-bottom:8px;">' + title + '</div>' +
  '<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border-collapse:collapse;border:1px solid #e3e3e3;border-radius:6px;overflow:hidden;">' +
  '<tr style="background:#fafafa;">' + head + '</tr>' + rows + '</table></td></tr>';

const html =
'<!DOCTYPE html><html><body style="margin:0;padding:0;background:#f4f4f5;">' +
'<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="background:#f4f4f5;padding:24px 12px;">' +
'<tr><td align="center">' +
'<table role="presentation" cellpadding="0" cellspacing="0" width="640" style="max-width:640px;width:100%;background:#ffffff;border-radius:10px;overflow:hidden;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Roboto,Arial,sans-serif;box-shadow:0 1px 3px rgba(0,0,0,.08);">' +

// header
'<tr><td style="background:#16181d;padding:26px 28px;">' +
'<div style="color:#ffffff;font-size:20px;font-weight:600;letter-spacing:-.01em;">Weekly Sales Report</div>' +
'<div style="color:#9aa0a6;font-size:13px;margin-top:4px;">Week ending ' + esc(data.weekEnding) + ' &nbsp;&middot;&nbsp; ' + (data.rowsProcessed || 0) + ' deals reviewed</div>' +
'</td></tr>' +

// headline number
'<tr><td style="padding:24px 28px 0 28px;">' +
'<table role="presentation" cellpadding="0" cellspacing="0" width="100%"><tr>' +
'<td style="background:#fafafa;border:1px solid #e9e9e9;border-radius:8px;padding:16px 18px;" width="50%">' +
'<div style="font-size:12px;color:#6b6b6b;text-transform:uppercase;letter-spacing:.05em;">Revenue this week</div>' +
'<div style="font-size:26px;font-weight:700;color:#16181d;margin-top:4px;">' + money(totalThis) + '</div>' +
'<div style="font-size:13px;margin-top:2px;">' + delta(totalPct) + ' <span style="color:#6b6b6b;">vs ' + money(totalLast) + ' last week</span></div>' +
'</td><td width="12"></td>' +
'<td style="background:#fafafa;border:1px solid #e9e9e9;border-radius:8px;padding:16px 18px;" width="50%">' +
'<div style="font-size:12px;color:#6b6b6b;text-transform:uppercase;letter-spacing:.05em;">Flagged problems</div>' +
'<div style="font-size:26px;font-weight:700;color:' + (data.flagCount ? '#b3261e' : '#1a7f4b') + ';margin-top:4px;">' + (data.flagCount || 0) + '</div>' +
'<div style="font-size:13px;color:#6b6b6b;margin-top:2px;">' + (data.flagCount ? 'need a look this week' : 'all clear') + '</div>' +
'</td></tr></table></td></tr>' +

section('Summary', ai.summary) +
flagBlock +

table('By salesperson',
  '<th ' + th + '>Name</th><th ' + thR + '>Revenue</th><th ' + thR + '>Last week</th><th ' + thR + '>Change</th><th ' + thR + '>Close rate</th>',
  peopleRows) +

table('By product',
  '<th ' + th + '>Product</th><th ' + thR + '>Units</th><th ' + thR + '>Last week</th><th ' + thR + '>Change</th><th ' + thR + '>Revenue</th>',
  productRows) +

section('Top performers', ai.top_performers) +
section('Needs attention', ai.underperformers) +
section('Product movement', ai.product_movement) +
actionBlock +

// footer
'<tr><td style="padding:26px 28px 28px 28px;">' +
'<div style="border-top:1px solid #ededed;padding-top:16px;">' +
'<a href="__DOC_LINK__" style="display:inline-block;background:#16181d;color:#ffffff;text-decoration:none;font-size:14px;font-weight:500;padding:10px 18px;border-radius:6px;">Open the full document</a>' +
'<div style="color:#9aa0a6;font-size:12px;margin-top:14px;line-height:1.5;">Generated automatically from the Sales sheet. All figures are calculated in the workflow, not written by AI.</div>' +
'</div></td></tr>' +

'</table></td></tr></table></body></html>';

// Plain version for the Google Doc
const plain = [
  'WEEKLY SALES REPORT',
  'Week ending ' + data.weekEnding,
  '',
  'SUMMARY',
  ai.summary || '',
  '',
  'TOP PERFORMERS',
  ai.top_performers || '',
  '',
  'NEEDS ATTENTION',
  ai.underperformers || '',
  '',
  'PRODUCT MOVEMENT',
  ai.product_movement || '',
  '',
  'FLAGGED PROBLEMS',
  flagList.length ? flagList.map(f => '- ' + f).join('\n') : 'None this week.',
  '',
  'SUGGESTED ACTIONS',
  actions.map((a, i) => (i + 1) + '. ' + a).join('\n'),
].join('\n');

return [{
  json: {
    html,
    plainText: plain,
    subject: 'Weekly Sales Report - ' + data.weekEnding + (data.flagCount ? ' (' + data.flagCount + ' flagged)' : ''),
    weekEnding: data.weekEnding,
    flagCount: data.flagCount,
  },
}];
